const fix=document.createElement('style');fix.textContent=`.modes{grid-template-columns:repeat(3,minmax(0,1fr))}.modes button,nav button{min-width:0}nav{width:100%;grid-template-columns:repeat(4,minmax(0,1fr))}.library-entry{margin:0 17px 10px;width:calc(100% - 34px);padding:10px 12px;border:1px solid #ffffff16;border-radius:13px;background:#292442cc;display:flex;align-items:center;text-align:left;gap:10px}.library-entry>i{width:34px;height:34px;border-radius:10px;background:#684ea0;display:grid;place-items:center;font-style:normal}.library-entry>span{display:grid;flex:1}.library-entry b{font-size:11px}.library-entry small{font-size:8px;color:#958da7;margin-top:3px}.connect-screen .intro{padding:22px 18px 13px}.connect-screen .intro h2{font-size:20px;margin:0 0 5px}.connect-screen .intro p{font-size:10px;color:#9690a5;margin:0}.services{padding:0 14px;display:grid;gap:9px}.service{padding:13px;border-radius:15px;background:#292541;border:1px solid #ffffff12;display:grid;grid-template-columns:42px 1fr auto;gap:11px;align-items:center}.service .logo{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;font-size:19px}.spotify{background:#1db954}.netease{background:#e7463c}.qq{background:#f2c94c;color:#413713}.service>span{display:grid}.service b{font-size:11px}.service small{font-size:8px;color:#918b9e;margin-top:4px}.service button{padding:7px 10px;border-radius:14px;background:#8d69d2;font-size:9px}.service button.connected{background:#ffffff10;color:#9a93a7}.consent{margin:15px 18px;padding:11px;border-radius:12px;background:#ffffff08;color:#918a9f;font-size:8px;line-height:1.55}.playlist-head{padding:18px 18px 7px;display:flex;justify-content:space-between}.playlist-head h3{margin:0;font-size:12px}.playlist-head small{font-size:8px;color:#9b94a8}.playlist-list{padding:0 14px;display:grid;gap:8px}.playlist{display:grid;grid-template-columns:46px 1fr auto;gap:10px;align-items:center;padding:8px;background:#292541;border-radius:13px}.playlist .art{width:46px;height:46px;border-radius:9px;display:grid;place-items:center;background:linear-gradient(135deg,#b67fd6,#4b5ba4);font-size:18px}.playlist:nth-child(2) .art{background:linear-gradient(135deg,#e48d92,#744c8f)}.playlist:nth-child(3) .art{background:linear-gradient(135deg,#89a9bc,#313d63)}.playlist>span{display:grid}.playlist b{font-size:10px}.playlist small{font-size:8px;color:#8e879d;margin-top:3px}.playlist button{font-size:17px}`;document.head.append(fix);
document.querySelector('.home .track').insertAdjacentHTML('beforebegin','<button class="library-entry" data-go="connect"><i>♫</i><span><b>连接我的音乐</b><small>Spotify · 网易云音乐 · QQ 音乐</small></span><em>›</em></button>');
document.querySelector('main').insertAdjacentHTML('beforeend',`<section class="screen connect-screen" data-screen="connect"><div class="bar"><button data-back>‹</button><div><b>连接音乐服务</b><small>导入你的歌单</small></div><button>•••</button></div><div class="intro"><h2>我的音乐世界</h2><p>连接账号后，Mori 可以陪你听已有歌单。</p></div><div class="services"><div class="service"><i class="logo spotify">●</i><span><b>Spotify</b><small>歌单、收藏与最近播放</small></span><button data-service="Spotify">连接</button></div><div class="service"><i class="logo netease">◎</i><span><b>网易云音乐</b><small>待官方合作接入</small></span><button data-service="网易云音乐">申请接入</button></div><div class="service"><i class="logo qq">♪</i><span><b>QQ 音乐</b><small>待官方合作接入</small></span><button data-service="QQ 音乐">申请接入</button></div></div><div class="consent">Mori 只读取你明确授权的音乐资料，不会获取密码，也不会把完整歌单用于模型训练。你可以随时解除连接。</div><div class="playlist-head"><h3>来自 Spotify 的歌单</h3><small>24 个歌单</small></div><div class="playlist-list"><div class="playlist"><i class="art">✦</i><span><b>深夜一个人听</b><small>48 首 · 2 小时 56 分</small></span><button data-list="深夜一个人听">›</button></div><div class="playlist"><i class="art">☁</i><span><b>最近喜欢</b><small>96 首 · 刚刚更新</small></span><button data-list="最近喜欢">›</button></div><div class="playlist"><i class="art">☾</i><span><b>安静工作</b><small>32 首 · 低打扰播放</small></span><button data-list="安静工作">›</button></div></div></section>`);
const ss=[...document.querySelectorAll('.screen')],tabs=[...document.querySelectorAll('nav button')];let stack=['home'],playing=false;function go(id,p=true){ss.forEach(s=>s.classList.toggle('active',s.dataset.screen===id));tabs.forEach(t=>t.classList.toggle('on',t.dataset.go===id));document.querySelector('nav').hidden=['call','quiet','connect'].includes(id);if(p&&stack.at(-1)!==id)stack.push(id)}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{stack.pop();go(stack.at(-1)||'home',false)});document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{playing=!playing;document.querySelectorAll('[data-play]').forEach(x=>x.textContent=playing?'Ⅱ':'▶');toast(playing?'正在播放 · 晚风':'音乐已暂停')});document.querySelectorAll('.chips button,.voices button').forEach(b=>b.onclick=()=>{[...b.parentElement.children].forEach(x=>x.classList.remove('on'));b.classList.add('on');toast('设置已更新')});document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{if(b.dataset.service==='Spotify'){b.textContent='已连接';b.classList.add('connected');toast('Spotify 歌单已同步')}else toast(`${b.dataset.service} 需要平台官方合作授权`)});document.querySelectorAll('[data-list]').forEach(b=>b.onclick=()=>{go('quiet');toast(`开始陪听「${b.dataset.list}」`)});scene.onclick=()=>toast('环境音已切换为「夜雨」');privacy.onclick=()=>toast('所有记忆都由你确认和管理');chatForm.onsubmit=e=>{e.preventDefault();let v=chatInput.value.trim();if(!v)return;messages.insertAdjacentHTML('beforeend',`<div class="msg me"><p>${v.replace(/[<>]/g,'')}</p></div>`);chatInput.value='';messages.scrollTop=messages.scrollHeight;setTimeout(()=>{messages.insertAdjacentHTML('beforeend','<div class="msg bot"><i>⌣</i><p>我在。我们可以慢慢说，也可以先听一会儿歌。</p></div>');messages.scrollTop=messages.scrollHeight},500)};let tm;function toast(x){let t=document.querySelector('.toast');t.textContent=x;t.classList.add('show');clearTimeout(tm);tm=setTimeout(()=>t.classList.remove('show'),1800)}
